parameters.jsCode:
// Arma el cuerpo de ship/generate con el esquema probado el 25 sep en el sandbox.
// Peso fijo: cada paca son 100 lb / 45 kg. Si piden más de una, se multiplica.
const p = $json.body || {};
const servicio = p.servicio === 'ground' ? 'ground' : 'ground_do';   // a sucursal por defecto
const faltan = ['orden_id', 'nombre', 'telefono', 'codigo_postal', 'ciudad', 'estado_mx']
  .filter(k => !p[k]);
if (servicio === 'ground_do' && !p.branch_code) faltan.push('branch_code');
if (faltan.length) {
  return [{ json: { ok: false, motivo: 'faltan_datos', faltan } }];
}

const cantidad = Number(p.cantidad || 1);
const peso = 45 * cantidad;
const destination = {
  name: p.nombre,
  company: '',
  email: p.email || '',
  phone: p.telefono,
  // ponytail: con ground_do la dirección es la de la sucursal, pero Envia igual pide
  // calle; si el bot no la capturó va un texto fijo.
  street: p.calle || 'Ocurre Paquete Express',
  number: p.numero || 'S/N',
  district: p.colonia || '',
  city: p.ciudad,
  state: p.estado_mx,
  country: 'MX',
  postalCode: p.codigo_postal
};
if (servicio === 'ground_do') destination.branchCode = p.branch_code;

return [{ json: {
  ok: true,
  orden_id: p.orden_id,
  contactId: p.contactId,
  cantidad,
  peso,
  envio: {
    origin: {
      name: $('Config').first().json.ALMACEN_NOMBRE,
      company: $('Config').first().json.ALMACEN_NOMBRE,
      email: $('Config').first().json.ALMACEN_EMAIL,
      phone: $('Config').first().json.ALMACEN_TELEFONO,
      street: $('Config').first().json.ALMACEN_CALLE,
      number: $('Config').first().json.ALMACEN_NUMERO,
      district: $('Config').first().json.ALMACEN_COLONIA,
      city: $('Config').first().json.ALMACEN_CIUDAD,
      state: $('Config').first().json.ALMACEN_ESTADO,
      country: 'MX',
      postalCode: $('Config').first().json.ALMACEN_CP
    },
    destination,
    packages: [{
      type: 'box',
      content: 'Ropa usada',
      amount: 1,
      name: `Paca x${cantidad}`,
      // ponytail: valor declarado fijo por paca, para el seguro; no es el precio de venta.
      declaredValue: 1000 * cantidad,
      lengthUnit: 'CM',
      weightUnit: 'KG',
      weight: peso,
      dimensions: { length: 80, width: 50, height: 50 }
    }],
    shipment: { carrier: 'paquetexpress', service: servicio, type: 1, reverse_pickup: 0, import: 0 },
    settings: { currency: 'MXN', printFormat: 'PDF', printSize: 'STOCK_4X6', comments: `Orden ${p.orden_id}` }
  }
} }];

// Saca el número de rastreo y la etiqueta de la respuesta probada el 25 sep.
// Envia devuelve errores con HTTP 200 y meta: 'error', así que se revisa aquí.
const r = $json;
const previo = $('Armar el envío').first().json;
if (r.meta === 'error') {
  return [{ json: { ok: false, motivo: 'envia_error', detalle: r.error, orden_id: previo.orden_id } }];
}
const g = (r.data || [])[0] || {};
if (!g.trackingNumber) {
  return [{ json: { ok: false, motivo: 'envia_sin_guia', respuesta: r, orden_id: previo.orden_id } }];
}
return [{ json: { ok: true, orden_id: previo.orden_id, contactId: previo.contactId,
                  cantidad: previo.cantidad, peso: previo.peso,
                  numero_guia: g.trackingNumber, etiqueta_pdf: g.label, track_url: g.trackUrl,
                  folio: g.folio, costo_guia: g.totalPrice,
                  fecha_envio: new Date().toISOString() } }];

parameters.jsonBody:
={{ JSON.stringify((() => {
  // Recolección mañana, de 9 a 18. Esquema de docs.envia.com/reference/schedule-pickup.
  const g = $json;
  const d = new Date(Date.now() + 24 * 3600 * 1000);
  return {
    origin: {
      name: $('Config').first().json.ALMACEN_NOMBRE, company: $('Config').first().json.ALMACEN_NOMBRE, email: $('Config').first().json.ALMACEN_EMAIL, phone: $('Config').first().json.ALMACEN_TELEFONO,
      street: $('Config').first().json.ALMACEN_CALLE, number: $('Config').first().json.ALMACEN_NUMERO, district: $('Config').first().json.ALMACEN_COLONIA,
      city: $('Config').first().json.ALMACEN_CIUDAD, state: $('Config').first().json.ALMACEN_ESTADO, country: 'MX', postalCode: $('Config').first().json.ALMACEN_CP
    },
    shipment: {
      type: 1, carrier: 'paquetexpress',
      pickup: { weightUnit: 'KG', totalWeight: g.peso, totalPackages: 1, date: d.toISOString().slice(0, 10),
                timeFrom: 9, timeTo: 18, carrier: 'paquetexpress', trackingNumbers: [g.numero_guia] }
    }
  };
})()) }}
